package ro.leo.visual;
import ro.leo.i18n.L;
import android.content.*;import android.net.Uri;import org.json.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.*;
/** A local bookmark only. Reading never starts playback. */
final class MusicResume {
 private static final java.util.concurrent.ThreadPoolExecutor writer=new java.util.concurrent.ThreadPoolExecutor(0,1,30,java.util.concurrent.TimeUnit.SECONDS,new java.util.concurrent.ArrayBlockingQueue<Runnable>(1),new java.util.concurrent.ThreadPoolExecutor.DiscardOldestPolicy());
 private static volatile Session recent;private static final java.util.concurrent.atomic.AtomicLong submitted=new java.util.concurrent.atomic.AtomicLong(),completed=new java.util.concurrent.atomic.AtomicLong();
 static boolean idle(){return completed.get()>=submitted.get();}
 static void forgetMemory(){recent=null;}
 static void schedule(Context context,MusicQueue queue,int position){if(queue.index<0)return;final MusicQueue copy=new MusicQueue();copy.set(new ArrayList<String>(queue.sources),new ArrayList<String>(queue.titles),queue.index);final int at=Math.max(0,position);final Context app=context.getApplicationContext();Session latest=new Session();latest.sources.addAll(copy.sources);latest.titles.addAll(copy.titles);latest.index=copy.index;latest.position=at;recent=latest;final long token=submitted.incrementAndGet();writer.execute(new Runnable(){public void run(){try{save(app,copy,at);}finally{completed.set(token);}}});}
 static final class Session{ArrayList<String> sources=new ArrayList<String>(),titles=new ArrayList<String>();int index,position;}
 static File file(Context c){return new File(c.getFilesDir(),"music-resume.json");}
 static JSONObject encode(MusicQueue queue,int position)throws Exception{if(queue.index<0)throw new IOException(L.t("Nicio piesă"));JSONArray uris=new JSONArray(),titles=new JSONArray();for(int n=0;n<queue.sources.size();n++){uris.put(queue.sources.get(n));titles.put(queue.titles.get(n));}return new JSONObject().put("version",1).put("sources",uris).put("titles",titles).put("index",queue.index).put("position",Math.max(0,position));}
 static Session decode(JSONObject data)throws Exception{if(data.getInt("version")!=1)throw new IOException(L.t("Versiune necunoscută"));JSONArray sources=data.getJSONArray("sources"),titles=data.getJSONArray("titles");if(sources.length()==0||sources.length()>500||titles.length()!=sources.length())throw new IOException(L.t("Coadă invalidă"));Session out=new Session();for(int n=0;n<sources.length();n++){String s=sources.getString(n),title=titles.getString(n);Uri u=Uri.parse(s);if(s.length()>4096||title.length()>4096||!("content".equals(u.getScheme())||"file".equals(u.getScheme())))throw new IOException(L.t("Sursă locală invalidă"));out.sources.add(s);out.titles.add(title);}out.index=data.getInt("index");out.position=data.getInt("position");if(out.index<0||out.index>=sources.length()||out.position<0)throw new IOException(L.t("Poziție invalidă"));return out;}
 static Session read(Context c)throws Exception{Session pending=recent;if(pending!=null){MusicQueue q=new MusicQueue();q.set(pending.sources,pending.titles,pending.index);return decode(encode(q,pending.position));}return decode(new JSONObject(new String(BackupEngine.atomicBytes(file(c),1024*1024),StandardCharsets.UTF_8)));}
 static void save(Context c,MusicQueue queue,int position){try{JSONObject data=encode(queue,position);decode(data);byte[] bytes=data.toString().getBytes(StandardCharsets.UTF_8);if(bytes.length<=1024*1024)BackupEngine.write(file(c),bytes);}catch(Exception ignored){}}
}
